#!/usr/bin/env python3
# PB23 AGE-ORT · 判据先冻 PREREG_PB23_ageorth.md · 器承 Exp10 读写分解
import os,json,time,base64,hashlib,copy,random
os.system("python -m pip uninstall -y -q torchao 2>/dev/null")
import numpy as np,torch
from transformers import AutoTokenizer,AutoModelForCausalLM
from peft import LoraConfig,get_peft_model,TaskType
PAYLOAD={"B1_13-24.jsonl": {"b64": "", "sha256": "e7e182f0b58c32b01fb288e9a3ed8cbcd359dde5c9ec3a6d651fbc8ffe527353", "orig_lines": 14256}, "B2_25-40.jsonl": {"b64": "", "sha256": "fda65917c3313504691d10733719ae25da8956de066a55226636bae8663ea014", "orig_lines": 38252}, "B3_41-62.jsonl": {"b64": "", "sha256": "c0185d1af663ecacce5ca49db2796a2b95b059ca5e333dab4ea45b09902202a7", "orig_lines": 39133}, "B1_13-24_held.jsonl": {"b64": "", "sha256": "2932729b283f1e0064f0b987ad9dda13eadf17275c49dc9042dfe848febf3ab4", "orig_lines": 2376}, "B2_25-40_held.jsonl": {"b64": "", "sha256": "ecf034516595dfa4531ac7f3152e0ade5fdb92fd35022f2c292d93dd60605e8f", "orig_lines": 6375}, "B3_41-62_held.jsonl": {"b64": "", "sha256": "629e814eaac4113e5101b41a97ccad2dd47a921fb2d7c845184b7e866df564da", "orig_lines": 6522}}
assert all(hashlib.sha256(base64.b64decode(v["b64"])).hexdigest()==v["sha256"] for v in PAYLOAD.values()),"料漂移即停"
DEV="cuda";OUT="/kaggle/working";M="/kaggle/input/models/qwen-lm/qwen2.5/transformers/0.5b-instruct/1"
B=["B1_13-24.jsonl","B2_25-40.jsonl","B3_41-62.jsonl"]
def load(f): return [json.loads(l) for l in base64.b64decode(PAYLOAD[f]["b64"]).decode().strip().split("\n")]
CORP={f:load(f) for f in B}
tok=AutoTokenizer.from_pretrained(M)
base=AutoModelForCausalLM.from_pretrained(M,dtype=torch.float16)
def enc(i):
    u,a=i["messages"][0]["content"],i["messages"][1]["content"]
    pre=tok.apply_chat_template([{"role":"user","content":u},{"role":"assistant","content":""}],tokenize=False,add_generation_prompt=True)
    full=tok.apply_chat_template([{"role":"user","content":u},{"role":"assistant","content":a}],tokenize=False)
    fi=tok(full,add_special_tokens=False)["input_ids"];pi=tok(pre,add_special_tokens=False)["input_ids"]
    return fi,[-100]*len(pi)+fi[len(pi):]
def newl(seed):
    global m
    m=None;torch.cuda.empty_cache();torch.manual_seed(seed);random.seed(seed)
    m=get_peft_model(copy.deepcopy(base),LoraConfig(task_type=TaskType.CAUSAL_LM,r=16,lora_alpha=32,lora_dropout=0.05,bias="none",
      target_modules=["q_proj","k_proj","v_proj","o_proj","gate_proj","up_proj","down_proj"])).to(DEV)
def train(items,ep):
    p=[enc(i) for i in items];opt=torch.optim.AdamW([q for q in m.parameters() if q.requires_grad],lr=1e-4);m.train()
    for e in range(ep):
        o=list(range(len(p)));random.shuffle(o)
        for k,ix in enumerate(o,1):
            fi,la=p[ix]
            l=m(input_ids=torch.tensor([fi],device=DEV),labels=torch.tensor([la],device=DEV)).loss/4
            l.backward()
            if k%4==0 or k==len(o):opt.step();opt.zero_grad()
def cap():
    g={}
    for n,p in m.named_parameters():
        if ".lora_" not in n:continue
        b=n.split(".lora_")[0];kd=n.split(".lora_")[1][0]
        g.setdefault(b,{})[kd]=p.detach().cpu().float().numpy()
    U={};V={}
    for b,d in g.items():
        U_,s,Vt=np.linalg.svd(d["B"]@d["A"],full_matrices=False)
        k=min(8,len(s));U[b]=U_[:,:k];V[b]=Vt[:k,:]
    return U,V
def ov(Sa,Sb):
    vs=[]
    for b in Sa:
        if b not in Sb:continue
        k=min(Sa[b].shape[1],Sb[b].shape[1])
        vs.append(np.linalg.norm(Sa[b][:,:k].T@Sb[b][:,:k],"fro")/np.sqrt(k))
    return round(float(np.mean(vs)),4) if vs else None
REP={"case":"PB23","cap":"等距240/40, orig_lines={'B1_': 2376, 'B2_': 6375, 'B3_': 6522}","seeds":[13,14,15],"runs":[]}
def fl(t):
    REP["_meta"]={"stage":t,"t":time.strftime("%H:%M:%S")}
    json.dump(REP,open(f"{OUT}/report_pb23.json","w"),ensure_ascii=False)
    print("REPORT_LINE::"+base64.b64encode(json.dumps(REP).encode()).decode()[:3800],flush=True)
# 臂A
A={}
for sd in [13,14,15]:
    for f in B:
        newl(sd);train(CORP[f],4);U,V=cap();A[(f,sd)]=(U,V)
        fl(f"A-{f.split('_')[0]}s{sd}")
pairs=[(B[0],B[1]),(B[1],B[2]),(B[0],B[2])]
tab={}
for x,y in pairs:
    w=[ov(A[(x,s)][0],A[(y,s)][0]) for s in [13,14,15]]
    r=[ov(A[(x,s)][1],A[(y,s)][1]) for s in [13,14,15]]
    tab[f"{x.split('_')[0]}~{y.split('_')[0]}"]={"write_ov":w,"read_ov":r}
    REP["runs"].append({"arm":"A","pair":f"{x}~{y}","write_ov":w,"read_ov":r});fl("A-pair")
# 臂B
lad={}
for sd in [13,14,15]:
    newl(sd);cps=[]
    for f in B:
        train(CORP[f],4);cps.append(cap())
    lad[sd]=[{"ov21":ov(cps[1][0],cps[0][0]),"ov32":ov(cps[2][0],cps[1][0])},
             {"ov_ladder_cum":ov(cps[2][0],cps[0][0])}]
mix={}
for sd in [13,14,15]:
    allc=CORP[B[0]]+CORP[B[1]]+CORP[B[2]]
    newl(sd);train(allc[:len(allc)//2],6);Uh,_=cap()
    train(allc[len(allc)//2:],6);Uf,_=cap()
    mix[sd]=ov(Uf,Uh)
REP["B"]={"ladder":{str(k):v for k,v in lad.items()},"mixed":{str(k):v for k,v in mix.items()}}
# 判读
def maj(vals,th,lt=True): return sum((v<th if lt else v>th) for v in vals)>=2
h_o1={f"{x.split('_')[0]}~{y.split('_')[0]}":maj(tab[f"{x.split('_')[0]}~{y.split('_')[0]}"]["write_ov"],0.15) for x,y in pairs}
n_ok=sum(1 for k,v in h_o1.items() if v)>=2
h_o3=maj([lad[s][1]["ov_ladder_cum"] for s in lad],max(mix.values()),lt=True)
dead=maj([min(tab[k]["write_ov"]) for k in tab],0.5,lt=False)
silent=any(v==1.0 for k in tab for v in tab[k]["write_ov"])
REP["verdict"]={"instrument":"哑枪停判" if silent else "活","H_o1":h_o1,"邻带正交主判":"过" if (not silent and n_ok) else "不过",
 "H_o3_序生维":"过" if (not silent and h_o3) else "不过","生死_全平行":"触发(降剂量案)" if (not silent and dead) else "未触发",
 "mixed_ov":mix}
fl("final")
print("DONE PB23",json.dumps(REP["verdict"],ensure_ascii=False),flush=True)